  // to the drawings in `icons.ts` (generated by scripts/gen-icons.mjs); screens never use emoji or
  // glyph characters as icons.
  import { ICONS } from './icons';
  export { ICONS };
  export type IconName = keyof typeof ICONS;
  export const isIcon = (n: string): n is IconName => n in ICONS;
</script>

<script lang="ts">
  interface Props { name: IconName; size?: number; fill?: boolean; label?: string; }
  let { name, size = 22, fill = false, label }: Props = $props();
</script>

